void deallocate(char*& p, const char* data, size_t max_size, block& b) {
    // Check if the block is the most recently allocated (top of the stack)
    if (static_cast<const char*>(b.ptr) + b.length == p) {
        // Reclaim the memory by moving the stack pointer back
        p = static_cast<char*>(b.ptr);
    }
    // Reset the block
    b.ptr = nullptr;
    b.length = 0;
}

void deallocate(char*& p, const char* data, size_t max_size, block& b) {
    // Check if the block is the most recently allocated (top of the stack)
    if (b.ptr && static_cast<const char*>(b.ptr) >= data && 
        static_cast<const char*>(b.ptr) + b.length <= data + max_size &&
        static_cast<const char*>(b.ptr) + b.length == p) {
        // Reclaim the memory by moving the stack pointer back
        p = static_cast<char*>(b.ptr);
    }
    // Reset the block
    b.ptr = nullptr;
    b.length = 0;
}

